import{_ as t,o as e,c as a,ae as o}from"./chunks/framework.Dzr56EFm.js";const c=JSON.parse('{"title":"设计趋势 - 2026-06-07","description":"","frontmatter":{"date":"2026-06-07T00:00:00.000Z","category":"UX Trend"},"headers":[],"relativePath":"daily/2026-06-07-uxtrend.md","filePath":"daily/2026-06-07-uxtrend.md"}'),n={name:"daily/2026-06-07-uxtrend.md"};function s(i,r,g,p,h,l){return e(),a("div",null,[...r[0]||(r[0]=[o('<h1 id="设计趋势-2026-06-07" tabindex="-1">设计趋势 - 2026-06-07 <a class="header-anchor" href="#设计趋势-2026-06-07" aria-label="Permalink to &quot;设计趋势 - 2026-06-07&quot;">​</a></h1><blockquote><p>AI交互方式、Prompt UX、Agent UX、Workflow</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日设计趋势领域聚焦于AI在工作流优化、产品设计、代理工作流设计模式的应用，以及AI时代下的视觉与网页设计趋势。最值得关注的是AI工作流优化的变革性技巧和AI代理工作流设计模式的探讨，这些趋势预示着设计领域的智能化和个性化发展。</p><hr><h3 id="_1-ai工作流优化-7个真正有效的变革性技巧" tabindex="-1">1. AI工作流优化：7个真正有效的变革性技巧 <a class="header-anchor" href="#_1-ai工作流优化-7个真正有效的变革性技巧" aria-label="Permalink to &quot;1. AI工作流优化：7个真正有效的变革性技巧&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@vicki-larson/ai-workflow-optimization-7-game-changing-tips-that-actually-work-414862126f5f" target="_blank" rel="noreferrer">AI Workflow Optimization: 7 Game-Changing Tips That Actually Work</a></p><p><strong>一句话摘要</strong>: 通过创建自定义AI提示和逐步优化工作流来提升效率。</p><p><strong>能解决什么问题</strong>: 设计师如何利用AI工具提升工作效率和设计质量。</p><p><strong>产品应用</strong>: 适用于需要优化设计工作流程的设计师，通过AI工具自动化重复性任务。</p><p><strong>示例场景</strong>: 设计师使用AI工具生成布局结构和颜色方案。</p><hr><h3 id="_2-产品设计师工作中的人工智能应用" tabindex="-1">2. 产品设计师工作中的人工智能应用 <a class="header-anchor" href="#_2-产品设计师工作中的人工智能应用" aria-label="Permalink to &quot;2. 产品设计师工作中的人工智能应用&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@mariamargarida/ai-in-my-design-workflow-as-a-product-designer-feb120d8fe38" target="_blank" rel="noreferrer">AI In My Design Workflow As a Product Designer</a></p><p><strong>一句话摘要</strong>: AI工具V0在快速原型设计和交互演示中的应用</p><p><strong>能解决什么问题</strong>: 解决复杂流程设计中的效率和直观性问题</p><p><strong>产品应用</strong>: 适用于快速原型设计，需与设计系统集成</p><p><strong>示例场景</strong>: 使用V0快速迭代单张截图的最终结果</p><hr><h3 id="_3-ai代理工作流设计模式概览" tabindex="-1">3. AI代理工作流设计模式概览 <a class="header-anchor" href="#_3-ai代理工作流设计模式概览" aria-label="Permalink to &quot;3. AI代理工作流设计模式概览&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/binome/ai-agent-workflow-design-patterns-an-overview-cf9e1f609696" target="_blank" rel="noreferrer">AI Agent Workflow Design Patterns — An Overview</a></p><p><strong>一句话摘要</strong>: 探讨AI代理工作流设计模式，包括ReAct模式和计划解决模式。</p><p><strong>能解决什么问题</strong>: 如何设计AI代理以有效执行复杂任务和问题解决。</p><p><strong>产品应用</strong>: 可应用于开发智能助手和自动化系统，提高任务执行效率。</p><p><strong>示例场景</strong>: 智能助手规划并执行制作一杯拿铁咖啡的步骤。</p><hr><h3 id="_4-2026年ai时代的美学-视觉与网页设计趋势" tabindex="-1">4. 2026年AI时代的美学：视觉与网页设计趋势 <a class="header-anchor" href="#_4-2026年ai时代的美学-视觉与网页设计趋势" aria-label="Permalink to &quot;4. 2026年AI时代的美学：视觉与网页设计趋势&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/design-bootcamp/aesthetics-in-the-ai-era-visual-web-design-trends-for-2026-5a0f75a10e98" target="_blank" rel="noreferrer">Aesthetics in the AI era: Visual + web design trends for 2026 - Medium</a></p><p><strong>一句话摘要</strong>: 设计师选择打破常规，引入复杂性，创造新的设计语言。</p><p><strong>能解决什么问题</strong>: 解决传统设计缺乏个性和创新的问题。</p><p><strong>产品应用</strong>: 适用于产品界面设计，通过引入新元素增强用户体验。</p><p><strong>示例场景</strong>: 未来感强烈的UI面板和半数字半有机的环境设计。</p><hr><h3 id="_5-设计代理性用户体验指南" tabindex="-1">5. 设计代理性用户体验指南 <a class="header-anchor" href="#_5-设计代理性用户体验指南" aria-label="Permalink to &quot;5. 设计代理性用户体验指南&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/ai-ux-designers/era-of-agentive-ux-not-agentic-64dd765a0372" target="_blank" rel="noreferrer">Designing for Agentive UX — A Guide</a></p><p><strong>一句话摘要</strong>: 通过规则、行为、触发器和例外设计智能代理体验。</p><p><strong>能解决什么问题</strong>: 如何让智能代理更自然地融入用户日常生活。</p><p><strong>产品应用</strong>: 可以应用到智能家居、个人助理等，通过环境变化自动执行任务。</p><p><strong>示例场景</strong>: 根据温度自动为宠物狗加水。</p><hr><h3 id="_6-ai在设计中的应用-改变我们的创造方式" tabindex="-1">6. AI在设计中的应用：改变我们的创造方式 <a class="header-anchor" href="#_6-ai在设计中的应用-改变我们的创造方式" aria-label="Permalink to &quot;6. AI在设计中的应用：改变我们的创造方式&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.figma.com/resource-library/ai-in-design" target="_blank" rel="noreferrer">AI in Design: Transforming the Way We Create - Figma</a></p><p><strong>一句话摘要</strong>: AI正在改变设计工作流程，提高效率和个性化。</p><p><strong>能解决什么问题</strong>: 提高设计效率，减少重复性工作，实现高度个性化设计。</p><p><strong>产品应用</strong>: 可以应用到产品设计中，通过AI自动化常规任务，设计师专注于策略和创意。</p><p><strong>示例场景</strong>: 使用AI设计工具为不同用户定制个性化界面。</p><hr><h3 id="_7-主动性用户体验时代" tabindex="-1">7. 主动性用户体验时代 <a class="header-anchor" href="#_7-主动性用户体验时代" aria-label="Permalink to &quot;7. 主动性用户体验时代&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://uxdesign.cc/the-agentic-era-of-ux-4b58634e410b" target="_blank" rel="noreferrer">The agentic era of UX</a></p><p><strong>一句话摘要</strong>: 主动性UX通过内置AI代理减轻用户的认知、创造和后勤负担。</p><p><strong>能解决什么问题</strong>: 解决用户在数字体验中需要独立思考、规划和导航的问题。</p><p><strong>产品应用</strong>: 适用于需要用户分析、决策和操作支持的软件产品。</p><p><strong>示例场景</strong>: Dovetail软件通过AI代理辅助用户分析访谈数据。</p><hr><h3 id="_8-2026年最佳ai设计工具11强" tabindex="-1">8. 2026年最佳AI设计工具11强 <a class="header-anchor" href="#_8-2026年最佳ai设计工具11强" aria-label="Permalink to &quot;8. 2026年最佳AI设计工具11强&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.figma.com/resource-library/ai-design-tools" target="_blank" rel="noreferrer">11 of the Best AI Design Tools for 2026</a></p><p><strong>一句话摘要</strong>: AI设计工具加速创意实现，无需专业技能。</p><p><strong>能解决什么问题</strong>: 解决设计过程中的重复性工作，提高效率和协作性。</p><p><strong>产品应用</strong>: 适用于需要快速迭代和跨设备适配的产品开发。</p><p><strong>示例场景</strong>: 产品团队使用Figma进行自然语言原型设计。</p><hr><h3 id="_9-提示工程-新兴的用户体验技能" tabindex="-1">9. 提示工程：新兴的用户体验技能 <a class="header-anchor" href="#_9-提示工程-新兴的用户体验技能" aria-label="Permalink to &quot;9. 提示工程：新兴的用户体验技能&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@katyneale/prompt-engineering-is-the-new-ux-skill-b3a58cb00e14" target="_blank" rel="noreferrer">Prompt Engineering is the New UX Skill</a></p><p><strong>一句话摘要</strong>: 指导用户在与AI互动中优化提示而不知</p><p><strong>能解决什么问题</strong>: 如何设计系统以引导用户自然提升与AI的互动</p><p><strong>产品应用</strong>: 适用于需要AI交互的产品，通过界面设计和逐步披露来提升用户体验</p><p><strong>示例场景</strong>: 心脏病专家和软件工程师使用AI工具时，需要不同的提示方法</p><hr><h3 id="_10-设计提示而非仅仅是文字-将流程转化为提示" tabindex="-1">10. 设计提示而非仅仅是文字：将流程转化为提示 <a class="header-anchor" href="#_10-设计提示而非仅仅是文字-将流程转化为提示" aria-label="Permalink to &quot;10. 设计提示而非仅仅是文字：将流程转化为提示&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/design-bootcamp/design-the-prompt-not-just-the-words-turning-flows-into-prompts-d2c53dc0a38e" target="_blank" rel="noreferrer">Design the prompt, not just the words: turning flows into prompts</a></p><p><strong>一句话摘要</strong>: 将用户流程转化为明确的提示，提高设计可理解性和迭代效率。</p><p><strong>能解决什么问题</strong>: 传统流程设计难以理解、验证和迭代，缺乏明确的步骤和状态。</p><p><strong>产品应用</strong>: 适用于需要清晰用户流程和状态管理的产品设计，如电商结账流程。</p><p><strong>示例场景</strong>: 电商平台使用流程提示优化结账体验</p><hr>',75)])])}const f=t(n,[["render",s]]);export{c as __pageData,f as default};
